import {HAL_WS_SUBPROTOCOL, credentialFromSubprotocol} from './index.js';
import type {
  IncomingMessage,
  ListSessionsMessage,
  OutgoingMessage,
  SessionListMessage,
  SessionSummaryFrame,
} from './index.js';
import * as subprotocol from './transport/ws/subprotocol.js';

describe('the package root', () => {
  it('exports the hal.v1 marker with the reader a WsAuthenticator uses', () => {
    expect({marker: HAL_WS_SUBPROTOCOL, reader: credentialFromSubprotocol}).toEqual({
      marker: subprotocol.HAL_WS_SUBPROTOCOL,
      reader: subprotocol.credentialFromSubprotocol,
    });
  });

  it('re-exports ListSessionsMessage, SessionSummaryFrame and SessionListMessage within the wire unions', () => {
    const bare: ListSessionsMessage = {type: 'list_sessions'};
    const paged: ListSessionsMessage = {
      type: 'list_sessions',
      limit: 10,
      before: {updatedAt: '2026-01-01T00:05:00.000Z', sessionId: 's3'},
    };
    const epochPaged: ListSessionsMessage = {
      type: 'list_sessions',
      before: {updatedAt: 1767225900000, sessionId: 's3'},
    };
    const summary: SessionSummaryFrame = {
      sessionId: 's2',
      createdAt: '2026-01-01T00:00:00.000Z',
      updatedAt: '2026-01-01T00:02:00.000Z',
      entryCount: 4,
    };
    const reply: SessionListMessage = {type: 'session_list', sessions: [summary]};
    const incoming: IncomingMessage[] = [bare, paged, epochPaged];
    const outgoing: OutgoingMessage = reply;

    expect({incomingTypes: incoming.map(frame => frame.type), outgoingType: outgoing.type}).toEqual({
      incomingTypes: ['list_sessions', 'list_sessions', 'list_sessions'],
      outgoingType: 'session_list',
    });
  });
});

