import type {IncomingMessage, ListSessionsMessage} from '../../types/messages.js';

const MAX_CONTENT_LENGTH = 10000;

interface ValidationSuccess {
  valid: true;
  data: IncomingMessage;
}

interface ValidationFailure {
  valid: false;
  error: string;
}

export type ValidationResult = ValidationSuccess | ValidationFailure;

type FrameValidator = (message: Record<string, unknown>) => ValidationResult;

type ParsedField<T> = {ok: true; value: T} | {ok: false; error: string};

type CursorPayload = NonNullable<ListSessionsMessage['before']>;

const FRAME_VALIDATORS = new Map<string, FrameValidator>([
  ['user_message', validateUserMessage],
  ['ping', validatePingMessage],
  ['list_sessions', validateListSessionsMessage],
]);

export function validateMessage(payload: unknown): ValidationResult {
  if (typeof payload !== 'object' || payload === null) {
    return {valid: false, error: 'Message must be an object'};
  }

  const message = payload as Record<string, unknown>;

  if (typeof message.type !== 'string') {
    return {valid: false, error: 'Message must have a type field'};
  }

  const validator = FRAME_VALIDATORS.get(message.type);
  if (!validator) {
    return {valid: false, error: `Unknown message type: ${message.type}`};
  }

  return validator(message);
}

function validateUserMessage(message: Record<string, unknown>): ValidationResult {
  if (typeof message.content !== 'string') {
    return {valid: false, error: 'user_message must have content string'};
  }

  const trimmed = message.content.trim();

  if (trimmed.length === 0) {
    return {valid: false, error: 'Message content cannot be empty'};
  }

  if (message.content.length > MAX_CONTENT_LENGTH) {
    return {valid: false, error: `Message content too long (max ${MAX_CONTENT_LENGTH} chars)`};
  }

  return {
    valid: true,
    data: {
      type: 'user_message',
      content: message.content,
    },
  };
}

function validatePingMessage(message: Record<string, unknown>): ValidationResult {
  if (typeof message.timestamp !== 'number') {
    return {valid: false, error: 'ping must have timestamp number'};
  }

  return {
    valid: true,
    data: {
      type: 'ping',
      timestamp: message.timestamp,
    },
  };
}

function validateListSessionsMessage(message: Record<string, unknown>): ValidationResult {
  const limit = readLimit(message.limit);
  if (!limit.ok) {
    return {valid: false, error: limit.error};
  }

  const before = readBefore(message.before);
  if (!before.ok) {
    return {valid: false, error: before.error};
  }

  const frame: ListSessionsMessage = {type: 'list_sessions'};
  if (limit.value !== undefined) {
    frame.limit = limit.value;
  }
  if (before.value !== undefined) {
    frame.before = before.value;
  }

  return {valid: true, data: frame};
}

function readLimit(raw: unknown): ParsedField<number | undefined> {
  if (raw === undefined) {
    return {ok: true, value: undefined};
  }
  if (!isValidLimit(raw)) {
    return {ok: false, error: 'list_sessions limit must be a non-negative integer'};
  }
  return {ok: true, value: raw};
}

function isValidLimit(raw: unknown): raw is number {
  if (typeof raw !== 'number') return false;
  return Number.isInteger(raw) && raw >= 0;
}

function readBefore(raw: unknown): ParsedField<CursorPayload | undefined> {
  if (raw === undefined) {
    return {ok: true, value: undefined};
  }
  if (!isPlainObject(raw)) {
    return {ok: false, error: 'list_sessions before must be an object'};
  }
  if (!isValidSessionId(raw.sessionId)) {
    return {ok: false, error: 'list_sessions before.sessionId must be 1-128 characters'};
  }
  if (!isValidTimestamp(raw.updatedAt)) {
    return {ok: false, error: 'list_sessions before.updatedAt must be a valid timestamp'};
  }
  return {
    ok: true,
    value: {
      updatedAt: raw.updatedAt,
      sessionId: raw.sessionId,
    },
  };
}

function isPlainObject(raw: unknown): raw is Record<string, unknown> {
  if (typeof raw !== 'object' || raw === null) return false;
  return !Array.isArray(raw);
}

const MAX_SESSION_ID_LENGTH = 128;

function isValidSessionId(raw: unknown): raw is string {
  if (typeof raw !== 'string') return false;
  return raw.length >= 1 && raw.length <= MAX_SESSION_ID_LENGTH;
}

function isValidTimestamp(raw: unknown): raw is string | number {
  if (typeof raw === 'number') {
    return Number.isFinite(raw) && Number.isFinite(new Date(raw).getTime());
  }
  if (typeof raw === 'string') {
    return raw.trim().length > 0 && Number.isFinite(new Date(raw).getTime());
  }
  return false;
}

